package com.spai.portal.web;import java.util.*;import com.spai.portal.asset.service.AssetService;import com.spai.portal.common.ApiResponse;import com.spai.portal.skill.domain.Skill;import com.spai.portal.skill.repository.SkillRepository;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/search")public class SearchController{private final AssetService assets;private final SkillRepository skills;public SearchController(AssetService assets,SkillRepository skills){this.assets=assets;this.skills=skills;}@GetMapping public ApiResponse<Map<String,Object>>search(@RequestParam String q){Map<String,Object>m=new LinkedHashMap<String,Object>();m.put("assets",assets.search(null,null,q));String lower=q.toLowerCase(Locale.ROOT);List<Skill>matched=new ArrayList<Skill>();for(Skill s:skills.findByStatusAndEnabledTrueOrderByDownloadCountDesc("PUBLISHED"))if((s.getName()+" "+s.getSlug()+" "+s.getDescription()).toLowerCase(Locale.ROOT).contains(lower))matched.add(s);m.put("skills",matched);return ApiResponse.ok(m);}}
